def cost(cases,H,native_each=0,source=True):
    # Two independent parents plus held-first per arm; at most3 once candidates,
    # one selected repeat, and one own hold per query. No saving is assumed.
    Q=cases*(4*H+2);parents=6*cases;source_worlds=3*cases if source else 0
    W=parents+4*Q+source_worlds;T=20*Q+4*source_worlds;slots=T//4
    model=math.ceil(T*MODEL_RATE*Fraction(5,4))+W*829464+18*MIB
    resets=cases if native_each else 0;native=cases*native_each;reset_raw=64*resets;native_raw=4*native+reset_raw
    native_bytes=math.ceil(native_raw*NATIVE_RATE*Fraction(5,4))+16*MIB+resets*32*MIB if native_each else 0
    states=2*W+Q+4;nonstate=W*160*1024+slots*128*1024+Q*16*1024+22*MIB
    # Large alternatives must be charged for >16MiB proof/decision requirements.
    proof=max(16*MIB,Q*12288);decision=max(16*MIB,Q*65536)
    total=model+native_bytes+proof+decision+32*MIB+512*MIB
    return dict(cases=cases,horizon_own_holds=H,comparison_queries=Q,comparison_parent_worlds=parents,comparison_candidate_repeat_worlds=4*Q,source_worlds=source_worlds,source_ticks=4*source_worlds,model_worlds=W,model_charged_ticks=T,model_wrapper_slots=slots,allocator_calls=Q,native_actions=native,native_resets=resets,native_reset_raw_ticks=reset_raw,native_total_raw_ticks=native_raw,total_physical_worlds=W+resets,max_live_worlds=2,max_simultaneous_constructor_step=1,model_raw_hard_bytes=model,native_raw_hard_bytes=native_bytes,state_objects_hard=states,state_bytes_hard=393216,nonstate_model_hard_bytes=nonstate,codec_format_bound_bytes=states*393216+nonstate,allocator_proof_hard_bytes=proof,decision_hard_bytes=decision,temp_bytes=32*MIB,reserve_each_volume_bytes=512*MIB,tmp_required_bytes=total,workspace_metadata_hard_bytes=64*MIB,workspace_required_bytes=576*MIB,model_file_count_hard=12*W+6*Q+states+64,native_file_count_hard=12*native+64*resets+64 if native_each else 0)

